    public bool IsCloseTo(Pressure other, double relativeTolerance = SIComparison.RelativeTolerance)
        => SIComparison.Equal(_si, other._si, relativeTolerance);
    public bool IsNaN() => double.IsNaN(_si);
    public bool IsInfinity() => double.IsInfinity(_si);

    // ---- Equality ----
    public bool Equals(Pressure other) => _si.Equals(other._si);
    public override bool Equals(object? obj) => obj is Pressure other && Equals(other);
    public override int GetHashCode() => _si.GetHashCode();
    public int CompareTo(Pressure other) => _si.CompareTo(other._si);
    public int CompareTo(object? obj) => obj is Pressure other ? CompareTo(other) : throw new ArgumentException($"Can't compare Pressure with {obj?.GetType().Name ?? "null"}");

    // ---- Text ----
    /// <summary>SI value with 4 significant digits, e.g. "1.5 kW" is printed as "1500 W".</summary>
    public override string ToString() => ToString(null, null);
    public string ToString(IFormatProvider formatProvider) => ToString(null, formatProvider);
    public string ToString(string? format) => ToString(format, null);
    public string ToString(string? format, IFormatProvider? formatProvider) => QuantityFormatter.Format(_si, PressureUnit.SI.Symbol, format, formatProvider);
    /// <summary>The value in <paramref name="unit"/>, e.g. "1.5 kW".</summary>
    public string ToString(PressureUnit unit, string? format = null, IFormatProvider? formatProvider = null) => QuantityFormatter.Format(As(unit), unit.Symbol, format, formatProvider);

    /// <summary>
    /// The same value, shown in <paramref name="unit"/>: <c>$"{p.ToUnit(PressureUnit.Bar)}"</c> prints "2 bar". Values are always
    /// stored in SI, so this is a display wrapper - it converts back to Pressure, but math on it needs the Pressure first.
    /// </summary>
    public QuantityInUnit<Pressure> ToUnit(PressureUnit unit) => new(this, unit);

    /// <summary>The value in SI. (A decimal in EngineeringUnits; the same number as <see cref="SI"/> here.)</summary>
    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
    public double AsSI => _si;

    /// <summary>Returns the same value: it is always stored in SI. (EngineeringUnits converts the unit here.)</summary>
    public Pressure ConvertToSI() => this;

}

/// <summary>Writes {"Value": si, "Unit": "Pa"}. Reads that (any unit of Pressure, by exact symbol) or a bare SI number - a unit of another quantity is rejected.</summary>
public sealed class PressureJsonConverter : JsonConverter<Pressure>
{
    public override Pressure Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        => Pressure.FromSI(QuantityJson.Read(ref reader, "Pressure", PressureUnit.BySymbol));

    public override void Write(Utf8JsonWriter writer, Pressure value, JsonSerializerOptions options)
        => QuantityJson.Write(writer, value.SI, PressureUnit.SI.Symbol);
}

public static partial class UnitMath
{
    [return: DimensionOf(nameof(value), PowerParameter = nameof(toPower))]
    public static UnknownUnit Pow(this Pressure value, int toPower) => new(Math.Pow(value.SI, toPower));

    [return: DimensionOf(nameof(value), Root = 2)]
    public static UnknownUnit Sqrt(this Pressure value) => new(Math.Sqrt(value.SI));

    public static Pressure Sum(this IEnumerable<Pressure> values)
    {
        double sum = 0;
        foreach (var v in values) sum += v.SI;
        return Pressure.FromSI(sum);
    }

    public static Pressure Average(this IEnumerable<Pressure> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : Pressure.FromSI(sum / count);
    }

    public static Pressure Min(this IEnumerable<Pressure> values) => Aggregate(values, Math.Min);
    public static Pressure Max(this IEnumerable<Pressure> values) => Aggregate(values, Math.Max);

    private static Pressure Aggregate(IEnumerable<Pressure> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return Pressure.FromSI(result);
    }
}
